const eventRecoveryTarget = `-- name: EventRecoveryTarget :one
SELECT o.id,o.recipient_claims,o.state AS receipt_state,p.progress::jsonb AS progress,
 (coalesce(event_recovery_failure_identity(p.progress)=$1::jsonb,false) AND coalesce(routed.state,p.progress->>'state','pending')='failed' AND (NOT o.recipient_claims OR coalesce(routed.state,'')='failed'))::boolean AS unchanged,
 a.status<>'deleted' AS target_available
FROM event_fanout_outbox o
JOIN apps a ON a.id=$2::uuid AND a.account_id=o.account_id
LEFT JOIN event_fanout_recipients routed ON routed.outbox_id=o.id AND routed.subscription_id=$3::text
CROSS JOIN LATERAL (SELECT o.recipient_progress->$3::text AS progress) p
WHERE o.id=$4::bigint AND o.account_id=$5::uuid
 AND EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(o.recipient_snapshot,'[]'::jsonb)) r WHERE r->>'id'=$3::text AND r->>'app_id'=a.id::text)
FOR UPDATE OF o
`

